const money = (n, digits = 0) => new Intl.NumberFormat('en-US', { maximumFractionDigits: digits, minimumFractionDigits: digits }).format(n);
const usd = n => '$' + money(n, 2);
const date = value => new Date(value).toLocaleDateString('zh-CN', { month: '2-digit', day: '2-digit' });
const nav = [
  ['overview', '业务总览', LayoutDashboard], ['market', '全球采购市场', Store], ['products', '我的商品', Package], ['inquiries', '询价与报价', Mail], ['orders', '订单管理', ShoppingBag], ['profit', '利润工作台', TrendingUp], ['logistics', '物流跟踪', Truck], ['documents', '贸易单证', Files], ['suppliers', '供应商管理', Users],
];
const pageTitles = Object.fromEntries(nav.map(([key, label]) => [key, label]));
async function api(path, options = {}) {
  const response = await fetch('/api' + path, { headers: { 'Content-Type': 'application/json' }, ...options });
  const body = await response.json();
  if (!response.ok) throw new Error(body.error || '请求失败，请重试');
  return body;
}
function download(name, rows) {
  const clean = v => { let s = String(v ?? ''); if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; return '"' + s.replaceAll('"', '""') + '"'; };
  const blob = new Blob(['\uFEFF' + rows.map(row => row.map(clean).join(',')).join('\r\n')], { type: 'text/csv;charset=utf-8;' });
  const url = URL.createObjectURL(blob), a = document.createElement('a'); a.href = url; a.download = name; a.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
}
function Badge({ children, tone = '' }) { return <span className={'badge ' + (tone || ({ '在售': 'green', '已完成': 'green', '已通过': 'green', '运输中': 'blue', '生产备货': 'purple', '待装运': 'blue', '待确认': 'orange', '待审核': 'orange', '待报价': 'orange', '已报价': 'green', '已下架': 'gray', '合同确认': 'blue', '需补充资料': 'orange' })[children] || 'gray')}>{children}</span>; }
function ProductImage({ type = 'coil', className = '' }) {
  const asset = catalogMedia[type];
  const [failed, setFailed] = useState(false);
  useEffect(() => setFailed(false), [type]);
  if (!asset || failed) return <div className="photo-unavailable" role="img" aria-label="品类照片暂不可用"><Package size={28}/><span>照片暂不可用</span></div>;
  return <img className={'steel-art product-photo ' + className} src={asset.src} alt={asset.alt} width="1200" height="800" loading="lazy" decoding="async" onError={() => setFailed(true)}/>;
}
function PortPhoto() {
  const asset = catalogMedia.port;
  return <div className="port-visual" aria-hidden="true">{asset && <img src={asset.src} alt="" width="1600" height="1000" fetchPriority="high"/>}<div className="port-photo-grid"/><span className="port-coordinate">GLOBAL SUPPLY / CONNECTED TRADE</span></div>;
}
function PhotoCredits() {
  return <div className="media-credits"><p className="muted">以下为真实摄影作品，仅用于工业品类与港口场景示意，不代表当前供应商、库存批次、检验结果或实际物流航次。展示有适配裁切与去饱和效果。照片来源与许可如下。</p>{Object.entries(catalogMedia).map(([key,m]) => <article key={key}><img src={m.src} alt={m.alt} width="120" height="80" loading="lazy"/><div><h3>{m.alt}</h3><p>{m.author}</p><a href={m.source} target="_blank" rel="noreferrer">原始作品 <ExternalLink size={12}/></a><a href={m.licenseUrl} target="_blank" rel="noreferrer">{m.license} <ExternalLink size={12}/></a></div></article>)}</div>;
}
function Modal({ title, children, onClose, wide = false }) {
  const ref = useRef(null);
  useEffect(() => {
    const previous = document.activeElement;
    ref.current?.focus();
    const key = e => {
      if (e.key === 'Escape') onClose();
      if (e.key === 'Tab') {
        const items = ref.current.querySelectorAll('button:not([disabled]), input, select, textarea, [tabindex="0"]');
        const first = items[0], last = items[items.length-1];
        if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus(); }
        if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus(); }
      }
    };
    document.addEventListener('keydown', key); document.body.style.overflow = 'hidden';
    return () => { document.removeEventListener('keydown', key); document.body.style.overflow = ''; previous?.focus(); };
  }, []);
  return <div className="modal-overlay" onMouseDown={e => e.target === e.currentTarget && onClose()}><section className={'modal '+(wide?'wide':'')} role="dialog" aria-modal="true" aria-label={title} tabIndex="-1" ref={ref}><div className="modal-title"><h2>{title}</h2><button className="icon-button" aria-label="关闭" onClick={onClose}><X size={20}/></button></div>{children}</section></div>;
}
function Field({ label, children, hint }) { const id = React.useId(); return <label className="field"><span id={id}>{label}</span>{['input','textarea','select'].includes(children.type) ? React.cloneElement(children, { 'aria-labelledby': id, ...(hint ? { 'aria-describedby': id+'-hint' } : {}) }) : children}{hint && <small id={id+'-hint'}>{hint}</small>}</label>; }
function Empty({ title = '暂无记录', description = '新记录将在这里展示', action }) { return <div className="empty"><Boxes size={38}/><h3>{title}</h3><p>{description}</p>{action}</div>; }
function SectionHead({ title, sub, action, children }) { return <div className="section-head"><div><h2>{title}{sub&&<span className="section-sub">{sub}</span>}</h2>{children}</div>{action}</div>; }
function PageHead({ eyebrow, title, description, actions }) { return <div className="page-head"><div>{eyebrow&&<div className="eyebrow">{eyebrow}</div>}<h1>{title}</h1><p>{description}</p></div><div className="page-actions">{actions}</div></div>; }

