  const [marketSupplier, setMarketSupplier] = useState(''), [role, setRole] = useState('供应商工作台'), [modal, setModal] = useState(null), [toast, setToast] = useState(''), [busy, setBusy] = useState(false), [mobile, setMobile] = useState(false), [notifications, setNotifications] = useState(false);
