  const [quoteItems,setQuoteItems] = useState(()=>{try{const x=JSON.parse(localStorage.getItem('sf-quote-basket')||'[]');return Array.isArray(x)?x.filter(i=>i&&typeof i.productId==='string'&&Number.isFinite(Number(i.quantity))).slice(0,20):[]}catch{return []}});
  useEffect(()=>{localStorage.setItem('sf-quote-basket',JSON.stringify(quoteItems))},[quoteItems]);
  const addToQuote = p => { if(quoteItems.some(x=>x.productId===p.id)){setToast('商品已在询价篮中');return} if(quoteItems.length>=20){setToast('询价篮最多容纳 20 款商品');return} setQuoteItems(x=>[...x,{productId:p.id,quantity:p.moq}]);setToast('已加入询价篮：'+p.name); };
  const updateQuote=(id,value)=>setQuoteItems(items=>items.map(x=>x.productId===id?{...x,quantity:value}:x));
  const removeQuote=id=>setQuoteItems(items=>items.filter(x=>x.productId!==id));
  const clearQuote=()=>setQuoteItems([]);
  const refresh = async () => { try { setData(await api('/bootstrap')); setError(''); } catch(e) { setError(e.message); } };
  useEffect(() => { refresh(); const change = () => { setPage(location.hash.slice(1) || 'market'); setMobile(false); window.scrollTo(0,0); }; window.addEventListener('hashchange', change); return () => window.removeEventListener('hashchange', change); }, []);
  useEffect(() => { const key = e => { if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'k') { e.preventDefault(); setModal({type:'search'}); } }; window.addEventListener('keydown', key); return () => window.removeEventListener('keydown', key); }, []);
  useEffect(() => { if (toast) { const t = setTimeout(() => setToast(''), 4500); return () => clearTimeout(t); } }, [toast]);
