      {modal.type==='success'&&<div className="success-content"><span className="success-circle"><Check size={33}/></span><h2>{modal.title}</h2><p>记录已保存至工作空间，刷新页面后仍可查看。</p><div className="success-id">业务编号 <strong>{modal.item.id}</strong></div><button className="btn primary" onClick={()=>{go(modal.item.id.startsWith('APP')?'suppliers':modal.item.id.startsWith('RFQ')?'inquiries':modal.item.productName?'orders':'products');setModal(null);}}>查看记录 <ArrowRight size={16}/></button></div>}
